t.script:

(function(){
    var container = document.getElementById('specsContainer');
    if(!container) return;

    var productSource = document.getElementById('layerProductTemplateOptionsSource');
    var variantSource = document.getElementById('layerVariantOptionsSource');
    var printFinishSource = document.getElementById('printFinishOptionsSource');
    var featureSource = document.getElementById('featureOptionsSource');
    var bagTypeSource = document.getElementById('fgProductOptionsSource');
    var quantityUomSource = document.getElementById('quantityUomOptionsSource');
    var previousReqOptions = document.getElementById('previousReqFormOptions');
    var formToken = container.dataset.formToken || '';
    var repeatImportCounter = 0;

    var newJobCheckbox = document.getElementById('newJobCheckbox');
    var repeatJobCheckbox = document.getElementById('repeatJobCheckbox');

    function normalizePreviousReqId(value){
        return String(value || '').trim().toUpperCase();
    }

    function findPreviousReqOption(value){
        if(!previousReqOptions) return false;
        var normalized = normalizePreviousReqId(value);
        if(!normalized) return false;
        return Array.prototype.slice.call(previousReqOptions.options).find(
            function(option){
                return normalizePreviousReqId(option.value) === normalized;
            }
        ) || false;
    }

    function setPreviousReqStatus(block, message, isError){
        if(!block) return;
        var status = block.querySelector('.previous-req-status');
        if(!status) return;
        status.textContent = message || '';
        status.classList.toggle('text-danger', !!isError);
        status.classList.toggle('text-success', !!message && !isError);
        status.classList.toggle('text-muted', !message);
    }

    function removeRepeatImportSiblings(sourceBlock){
        if(!sourceBlock) return;
        var group = sourceBlock.dataset.repeatImportGroup || '';
        if(!group) return;
        container.querySelectorAll('.spec-block').forEach(function(block){
            if(block !== sourceBlock && block.dataset.repeatImportGroup === group){
                block.remove();
            }
        });
    }

    function importPreviousRequirement(sourceBlock, payload){
        var specifications = payload && payload.specifications
            ? payload.specifications
            : [];
        if(!sourceBlock || !specifications.length){
            setPreviousReqStatus(
                sourceBlock,
                'No product specification data was found for this REQ ID.',
                true
            );
            return;
        }

        removeRepeatImportSiblings(sourceBlock);

        repeatImportCounter += 1;
        var group = 'repeat-' + repeatImportCounter;
        var reqId = String(payload.req_id || '').trim();
        var normalizedReqId = normalizePreviousReqId(reqId);
        var targetBlock = false;
        var previousTarget = false;

        specifications.forEach(function(specData, specIndex){
            if(specIndex === 0){
                targetBlock = newSpecBlock(0);
                sourceBlock.replaceWith(targetBlock);
            } else {
                targetBlock = newSpecBlock(0);
                previousTarget.insertAdjacentElement('afterend', targetBlock);
            }

            targetBlock.dataset.repeatImportGroup = group;
            setupComputedFields(targetBlock);

            var values = Object.assign({}, specData || {});
            values.previous_req_form = reqId;
            applySpecData(targetBlock, values);

            var previousInput = targetBlock.querySelector(
                '.previous-req-form-input'
            );
            if(previousInput){
                previousInput.value = reqId;
                previousInput.dataset.loadedReqId = normalizedReqId;
            }
            previousTarget = targetBlock;
        });

        updatePreviousReqFormVisibility();
        updateLabels();
        updateAddButtons();
        setPreviousReqStatus(
            container.querySelector(
                '.spec-block[data-repeat-import-group="' + group + '"]'
            ),
            specifications.length > 1
                ? 'Loaded ' + specifications.length + ' designs from ' + reqId + '.'
                : 'Loaded data from ' + reqId + '.',
            false
        );
    }

    function loadPreviousRequirement(block, input){
        if(
            !block
            || !input
            || !formToken
            || !repeatJobCheckbox
            || !repeatJobCheckbox.checked
        ){
            return;
        }

        var typedReqId = String(input.value || '').trim();
        if(!typedReqId){
            input.dataset.loadedReqId = '';
            setPreviousReqStatus(block, '', false);
            return;
        }

        // Prefer the canonical value from the datalist when it is
        // available, but also allow an exact REQ ID to be pasted
        // manually even when the browser has not opened the list.
        var option = findPreviousReqOption(typedReqId);
        var reqId = option
            ? String(option.value || '').trim()
            : typedReqId;
        var normalizedReqId = normalizePreviousReqId(reqId);
        if(input.dataset.loadedReqId === normalizedReqId){
            return;
        }

        input.value = reqId;
        input.dataset.loadingReqId = normalizedReqId;
        setPreviousReqStatus(block, 'Loading ' + reqId + '...', false);

        var url = '/requirement/form/previous-data/'
            + encodeURIComponent(formToken)
            + '?req_id=' + encodeURIComponent(reqId);

        fetch(url, {
            method: 'GET',
            headers: {'Accept': 'application/json'},
            credentials: 'same-origin'
        }).then(function(response){
            return response.json().then(function(payload){
                if(!response.ok || !payload || !payload.ok){
                    throw new Error(
                        payload && payload.message
                            ? payload.message
                            : 'Unable to load the previous requirement.'
                    );
                }
                return payload;
            });
        }).then(function(payload){
            if(
                !block.isConnected
                || input.dataset.loadingReqId !== normalizedReqId
                || normalizePreviousReqId(input.value) !== normalizedReqId
            ){
                return;
            }
            input.dataset.loadedReqId = normalizedReqId;
            importPreviousRequirement(block, payload);
        }).catch(function(error){
            if(!block.isConnected) return;
            input.dataset.loadedReqId = '';
            setPreviousReqStatus(
                block,
                error && error.message
                    ? error.message
                    : 'Unable to load the previous requirement.',
                true
            );
        });
    }

    function closePreviousReqDropdown(block){
        if(!block) return;
        var menu = block.querySelector('.previous-req-dropdown');
        if(menu){ menu.classList.add('d-none'); }
    }

    function renderPreviousReqDropdown(block, filterValue){
        if(!block || !previousReqOptions) return;
        var menu = block.querySelector('.previous-req-dropdown');
        if(!menu) return;

        var normalizedFilter = normalizePreviousReqId(filterValue);
        var options = Array.prototype.slice.call(previousReqOptions.options);
        var matches = options.filter(function(option){
            var value = String(option.value || '').trim();
            if(!value) return false;
            return !normalizedFilter
                || normalizePreviousReqId(value).indexOf(normalizedFilter) !== -1;
        });

        menu.innerHTML = '';
        if(!matches.length){
            var empty = document.createElement('div');
            empty.className = 'previous-req-empty';
            empty.textContent = 'No matching REQ ID found';
            menu.appendChild(empty);
            menu.classList.remove('d-none');
            return;
        }

        matches.forEach(function(option){
            var item = document.createElement('div');
            item.className = 'previous-req-option';
            item.setAttribute('role', 'option');
            item.dataset.value = String(option.value || '').trim();
            item.textContent = item.dataset.value;
            menu.appendChild(item);
        });
        menu.classList.remove('d-none');
        menu.scrollTop = 0;
    }

    function setupPreviousRequirementLookup(block){
        var input = block.querySelector('.previous-req-form-input');
        var menu = block.querySelector('.previous-req-dropdown');
        if(!input || !menu || input.dataset.lookupBound === '1') return;
        input.dataset.lookupBound = '1';

        var timer = false;
        function scheduleLookup(){
            if(timer){ window.clearTimeout(timer); }
            input.dataset.loadedReqId = (
                input.dataset.loadedReqId
                && input.dataset.loadedReqId === normalizePreviousReqId(input.value)
            ) ? input.dataset.loadedReqId : '';

            renderPreviousReqDropdown(block, input.value);

            if(!String(input.value || '').trim()){
                setPreviousReqStatus(block, '', false);
                return;
            }

            if(findPreviousReqOption(input.value)){
                setPreviousReqStatus(block, 'REQ ID matched. Loading...', false);
                timer = window.setTimeout(function(){
                    closePreviousReqDropdown(block);
                    loadPreviousRequirement(block, input);
                }, 250);
            } else {
                setPreviousReqStatus(
                    block,
                    'Paste the complete REQ ID or select one from the list.',
                    false
                );
            }
        }

        input.addEventListener('focus', function(){
            renderPreviousReqDropdown(block, input.value);
        });
        input.addEventListener('click', function(){
            renderPreviousReqDropdown(block, input.value);
        });
        input.addEventListener('input', scheduleLookup);
        input.addEventListener('paste', function(){
            if(timer){ window.clearTimeout(timer); }
            window.setTimeout(function(){
                renderPreviousReqDropdown(block, input.value);
                loadPreviousRequirement(block, input);
            }, 50);
        });
        input.addEventListener('change', function(){
            if(timer){ window.clearTimeout(timer); }
            loadPreviousRequirement(block, input);
        });
        input.addEventListener('blur', function(){
            if(timer){ window.clearTimeout(timer); }
            window.setTimeout(function(){
                closePreviousReqDropdown(block);
                loadPreviousRequirement(block, input);
            }, 120);
        });
        input.addEventListener('keydown', function(event){
            if(event.key === 'Escape'){
                closePreviousReqDropdown(block);
                input.blur();
            }
        });

        menu.addEventListener('mousedown', function(event){
            var item = event.target.closest('.previous-req-option');
            if(!item) return;
            event.preventDefault();
            if(timer){ window.clearTimeout(timer); }
            input.value = item.dataset.value || '';
            input.dataset.loadedReqId = '';
            closePreviousReqDropdown(block);
            loadPreviousRequirement(block, input);
        });
    }

    function updatePreviousReqFormVisibility(){
        var showPreviousReq = !!(repeatJobCheckbox && repeatJobCheckbox.checked);
        container.querySelectorAll('.previous-req-form-wrap').forEach(function(wrap){
            wrap.classList.toggle('d-none', !showPreviousReq);
            var input = wrap.querySelector('.previous-req-form-input');
            if(input){ input.disabled = !showPreviousReq; }
            if(!showPreviousReq){
                closePreviousReqDropdown(wrap.closest('.spec-block'));
            }
        });
    }

    if(newJobCheckbox && repeatJobCheckbox){
        newJobCheckbox.addEventListener('change', function(){
            if(newJobCheckbox.checked){ repeatJobCheckbox.checked = false; }
            updatePreviousReqFormVisibility();
        });
        repeatJobCheckbox.addEventListener('change', function(){
            if(repeatJobCheckbox.checked){ newJobCheckbox.checked = false; }
            updatePreviousReqFormVisibility();
        });
    }

    var contractType = document.getElementById('contractType');
    var durationWrap = document.querySelector('.contract-duration-wrap');
    var durationInput = document.querySelector('.contract-duration-input');
    function toggleContractDuration(){
        if(!contractType || !durationWrap || !durationInput) return;
        var isLong = contractType.value === 'long_term_supply';
        durationWrap.style.display = isLong ? 'block' : 'none';
        durationInput.required = isLong;
        if(!isLong){ durationInput.value = ''; }
    }
    if(contractType){
        toggleContractDuration();
        contractType.addEventListener('change', toggleContractDuration);
    }

    function specIndex(){ return container.querySelectorAll('.spec-block').length; }

    function updateLabels(){
        container.querySelectorAll('.spec-block').forEach(function(block, i){
            var lbl = block.querySelector('.spec-label');
            if(lbl) lbl.textContent = 'Design ' + (i + 1);
            var removeButton = block.querySelector('.remove-spec');
            if(removeButton){
                removeButton.classList.toggle('d-none', i === 0);
            }
            block.querySelectorAll('[name]').forEach(function(el){
                el.name = el.name.replace(/spec\[\d+\]/, 'spec[' + i + ']');
            });
        });
    }

    function updateAddButtons(){
        document.querySelectorAll('.design-actions').forEach(function(div){ div.remove(); });
        var blocks = container.querySelectorAll('.spec-block');
        if(blocks.length > 0){
            var last = blocks[blocks.length - 1];
            var div = document.createElement('div');
            div.className = 'col-12 text-end mt-3 d-flex gap-2 justify-content-end design-actions';
            div.innerHTML = `
                <button type="button" class="btn req-action-btn btn-sm duplicate-design-btn">Duplicate</button>
                <button type="button" class="btn req-action-btn btn-sm add-another-btn">+ Add Another Design</button>`;
            last.querySelector('.card-body .row').appendChild(div);
        }
    }

    function selectedValues(select){
        return Array.prototype.slice.call(select.selectedOptions).map(function(option){ return option.value; });
    }

    function setOptions(select, html){
        select.innerHTML = html || '<option value="">-- Select --</option>';
    }

    function populateBagTypeOptions(select, fgType, preferredValue){
        if(!select || !bagTypeSource) return;
        var options = Array.prototype.slice.call(bagTypeSource.options);
        select.innerHTML = '';
        options.forEach(function(option){
            var optionFgType = String(option.dataset.fgType || '').trim();
            if(!option.value || optionFgType === fgType){
                select.appendChild(option.cloneNode(true));
            }
        });
        if(preferredValue){
            select.value = String(preferredValue);
        }
    }

    function setupCrmMultiSelect(block, selector, source, inputName, placeholder){
        var wrapper = block.querySelector(selector);
        if(!wrapper || !source) return;
        var toggle = wrapper.querySelector('.multi-toggle');
        var menu = wrapper.querySelector('.crm-multi-menu');
        var tags = wrapper.querySelector('.selected-tags');
        menu.innerHTML = source.innerHTML;
        menu.querySelectorAll('input[type="checkbox"]').forEach(function(input){
            input.name = inputName;
        });

        function checkedInputs(){
            return Array.prototype.slice.call(menu.querySelectorAll('input[type="checkbox"]:checked'));
        }

        function refreshLabel(){
            var checked = checkedInputs();
            if(toggle){
                var labels = checked.map(function(input){
                    return input.dataset.label || input.parentElement.textContent.trim();
                });
                toggle.textContent = labels.length ? labels.join(', ') : placeholder;
                toggle.title = labels.join(', ');
                toggle.classList.toggle('text-muted', !labels.length);
            }
            if(tags){
                tags.innerHTML = '';
            }
        }

        function positionMenu(){
            if(!toggle || menu.classList.contains('d-none')) return;
            var rect = toggle.getBoundingClientRect();
            var gap = 4;
            var viewportPadding = 12;
            var availableBelow = window.innerHeight - rect.bottom - gap - viewportPadding;
            var availableAbove = rect.top - gap - viewportPadding;
            var openAbove = availableBelow < 180 && availableAbove > availableBelow;
            var maxHeight = Math.max(140, Math.min(320, openAbove ? availableAbove : availableBelow));

            menu.style.left = Math.max(viewportPadding, rect.left) + 'px';
            menu.style.width = Math.max(220, rect.width) + 'px';
            menu.style.maxHeight = maxHeight + 'px';
            menu.style.top = openAbove
                ? Math.max(viewportPadding, rect.top - maxHeight - gap) + 'px'
                : Math.min(window.innerHeight - viewportPadding, rect.bottom + gap) + 'px';
        }

        function closeMenu(){
            menu.classList.add('d-none');
        }

        if(toggle){
            toggle.addEventListener('click', function(ev){
                ev.preventDefault();
                var willOpen = menu.classList.contains('d-none');
                document.querySelectorAll('.crm-multi-menu:not(.d-none)').forEach(function(other){
                    if(other !== menu){ other.classList.add('d-none'); }
                });
                menu.classList.toggle('d-none', !willOpen);
                if(willOpen){
                    positionMenu();
                    menu.focus({preventScroll: true});
                }
            });
        }
        menu.setAttribute('tabindex', '-1');
        menu.addEventListener('wheel', function(ev){
            var atTop = menu.scrollTop <= 0;
            var atBottom = Math.ceil(menu.scrollTop + menu.clientHeight) >= menu.scrollHeight;
            if((ev.deltaY < 0 && !atTop) || (ev.deltaY > 0 && !atBottom)){
                ev.stopPropagation();
            }
        }, {passive: true});
        window.addEventListener('resize', positionMenu);
        window.addEventListener('scroll', positionMenu, true);
        menu.addEventListener('change', function(){
            refreshLabel();
            if(wrapper.classList.contains('feature-multi')){
                updateFeatureRules(block);
            }
        });
        document.addEventListener('click', function(ev){
            if(!wrapper.contains(ev.target)){
                closeMenu();
            }
        });
        refreshLabel();
    }

    function updateFeatureRules(block){
        var wrapper = block.querySelector('.feature-multi');
        if(!wrapper) return;
        var inputs = Array.prototype.slice.call(wrapper.querySelectorAll('input[type="checkbox"]'));
        var values = inputs.filter(function(input){ return input.checked; }).map(function(input){ return input.dataset.code; });
        var hasNormalZipper = values.indexOf('normal_zipper') >= 0;
        var hasTearZipper = values.indexOf('tear_zipper') >= 0;

        if(hasNormalZipper && hasTearZipper){
            inputs.forEach(function(input){
                if(input.dataset.code === 'tear_zipper'){
                    input.checked = false;
                }
            });
            hasTearZipper = false;
        }

        inputs.forEach(function(input){
            if(input.dataset.code === 'tear_zipper'){
                input.disabled = hasNormalZipper;
            }
            if(input.dataset.code === 'normal_zipper'){
                input.disabled = hasTearZipper;
            }
            if(input.dataset.code === 'tear_notch' || input.dataset.code === 'easy_tear_laser'){
                input.disabled = hasTearZipper;
                if(hasTearZipper){ input.checked = false; }
            }
            input.closest('label').classList.toggle('text-muted', input.disabled);
        });

        var toggle = wrapper.querySelector('.multi-toggle');
        var tags = wrapper.querySelector('.selected-tags');
        var checked = inputs.filter(function(input){ return input.checked; });
        if(toggle){
            var labels = checked.map(function(input){
                return input.dataset.label || input.parentElement.textContent.trim();
            });
            toggle.textContent = labels.length ? labels.join(', ') : 'Select Features';
            toggle.title = labels.join(', ');
            toggle.classList.toggle('text-muted', !labels.length);
        }
        if(tags){
            tags.innerHTML = '';
        }
    }

    function validateMultiSelects(){
        var isValid = true;
        container.querySelectorAll('.crm-multi[data-required="1"]').forEach(function(wrapper){
            var checked = wrapper.querySelectorAll('input[type="checkbox"]:checked').length;
            var toggle = wrapper.querySelector('.multi-toggle');
            if(toggle){ toggle.classList.toggle('is-invalid', !checked); }
            if(!checked && isValid){
                wrapper.scrollIntoView({behavior: 'smooth', block: 'center'});
            }
            isValid = isValid && !!checked;
        });
        if(!isValid){
            alert('Please select the required Features options.');
        }
        return isValid;
    }

    var mainForm = container.closest('form');
    if(mainForm){
        mainForm.addEventListener('submit', function(ev){
            var submitter = ev.submitter;
            if(submitter && submitter.name === 'internal_save'){
                return;
            }
            if(!validateMultiSelects()){
                ev.preventDefault();
            }
        });
    }

    function getSpecFieldKey(name){
        var match = (name || '').match(/^spec\[\d+\]\[(.+)\]$/);
        return match ? match[1] : false;
    }

    function collectSpecData(block){
        var data = {};
        block.querySelectorAll('input[name], select[name], textarea[name]').forEach(function(el){
            var key = getSpecFieldKey(el.name);
            if(!key) return;
            if(el.type === 'checkbox'){
                data[key] = data[key] || [];
                if(el.checked){ data[key].push(el.value); }
            } else if(el.type === 'radio'){
                if(el.checked){ data[key] = el.value; }
            } else {
                data[key] = el.value;
            }
        });
        return data;
    }

    function setFieldValue(block, key, value){
        var selector = '[name$="[' + key + ']"]';
        var fields = Array.prototype.slice.call(block.querySelectorAll(selector));
        fields.forEach(function(el){
            if(el.type === 'checkbox'){
                el.checked = Array.isArray(value) && value.indexOf(el.value) >= 0;
            } else if(el.type === 'radio'){
                el.checked = value === el.value;
            } else {
                el.value = value || '';
            }
        });
    }

    function applySpecData(block, data){
        for(var layerNo = 2; layerNo <= 10; layerNo++){
            if(
                data['layer_' + layerNo + '_product_tmpl_id'] ||
                data['layer_' + layerNo + '_variant_id'] ||
                data['layer_' + layerNo + '_thickness']
            ){
                showExtraLayer(block, String(layerNo));
            }
        }
        var productKeys = [];
        for(var productLayer = 1; productLayer <= 10; productLayer++){
            productKeys.push('layer_' + productLayer + '_product_tmpl_id');
        }
        productKeys.forEach(function(key){
            setFieldValue(block, key, data[key]);
            var productSelect = block.querySelector('[name$="[' + key + ']"]');
            if(productSelect){ productSelect.dispatchEvent(new Event('change', {bubbles: true})); }
        });
        Object.keys(data).forEach(function(key){
            if(key.indexOf('layer_') === 0 && key.indexOf('_product_tmpl_id') > 0){ return; }
            setFieldValue(block, key, data[key]);
        });
        block.querySelectorAll('.layer-variant-select').forEach(function(select){
            select.dispatchEvent(new Event('change', {bubbles: true}));
        });
        block.querySelectorAll('.crm-multi-menu').forEach(function(menu){
            menu.dispatchEvent(new Event('change', {bubbles: true}));
        });
        var colorSelect = block.querySelector('.color-reference-select');
        if(colorSelect){ colorSelect.dispatchEvent(new Event('change', {bubbles: true})); }
        var fgTypeSelect = block.querySelector('.fg-type-select');
        if(fgTypeSelect){
            fgTypeSelect.dispatchEvent(new Event('change', {bubbles: true}));
        }
        var bagSelect = block.querySelector('.fg-product-select');
        if(bagSelect){
            setFieldValue(block, 'bag_type_product_tmpl_id', data.bag_type_product_tmpl_id);
            bagSelect.dispatchEvent(new Event('change', {bubbles: true}));
        }
        updateFeatureRules(block);
        updateTotalThickness(block);
    }

    function duplicateDesign(sourceBlock){
        var source = sourceBlock || container.querySelector('.spec-block:last-child');
        if(!source) return;
        var data = collectSpecData(source);
        var idx = specIndex();
        var block = newSpecBlock(idx);
        container.appendChild(block);
        setupComputedFields(block);
        applySpecData(block, data);
        updatePreviousReqFormVisibility();
        updateLabels();
        updateAddButtons();
    }

    function setupLayerProductFields(block){
        block.querySelectorAll('.layer-product-select').forEach(function(productSelect){
            var layerNo = productSelect.dataset.layer;
            var thicknessInput = block.querySelector('.layer-thickness[data-layer="' + layerNo + '"]');
            var thicknessDisplay = block.querySelector('.layer-thickness-display[data-layer="' + layerNo + '"]');
            if(productSource){ setOptions(productSelect, productSource.innerHTML); }

            function updateThicknessFromProduct(){
                var selected = productSelect.options[productSelect.selectedIndex];
                var thickness = selected ? (selected.dataset.thickness || '') : '';
                var value = thickness && parseFloat(thickness) > 0
                    ? parseFloat(thickness).toString()
                    : '';
                if(thicknessInput){ thicknessInput.value = value; }
                if(thicknessDisplay){ thicknessDisplay.value = value; }
                updateTotalThickness(block);
            }

            productSelect.addEventListener('change', updateThicknessFromProduct);
            updateThicknessFromProduct();
        });
    }

    function updateTotalThickness(block){
        var totalInput = block.querySelector('.total-thickness');
        if(!totalInput) return;
        var total = 0;
        block.querySelectorAll('.layer-thickness').forEach(function(input){
            total += parseFloat(input.value || 0);
        });
        totalInput.value = total ? total.toFixed(2).replace(/\.00$/, '') : '';
    }

    function setupColorReference(block){
        var colorSelect = block.querySelector('.color-reference-select');
        var wrap = block.querySelector('.color-reference-type-wrap');
        if(!colorSelect || !wrap) return;
        var radios = Array.prototype.slice.call(wrap.querySelectorAll('input[type="radio"]'));
        function toggleColorReferenceType(){
            var show = colorSelect.value === 'yes';
            wrap.classList.toggle('d-none', !show);
            radios.forEach(function(radio){
                radio.required = show;
                if(!show){ radio.checked = false; }
            });
        }
        colorSelect.addEventListener('change', toggleColorReferenceType);
        toggleColorReferenceType();
    }

    function setLayerVisibility(block, layerNo, show){
        block.querySelectorAll('.layer-extra[data-layer="' + layerNo + '"]').forEach(function(wrap){
            wrap.classList.toggle('d-none', !show);
            wrap.querySelectorAll('input, select, textarea').forEach(function(field){
                field.disabled = !show;
                if(field.classList.contains('layer-product-select')){
                    field.required = show;
                }
                if(!show){
                    field.value = '';
                }
            });
        });
        updateTotalThickness(block);
        refreshAddLayerButton(block);
    }

    function refreshAddLayerButton(block){
        var button = block.querySelector('.add-layer-btn');
        if(!button) return;
        var nextLayer = false;
        for(var layerNo = 2; layerNo <= 10; layerNo++){
            if(block.querySelector('.layer-extra[data-layer="' + layerNo + '"].d-none')){
                nextLayer = layerNo;
                break;
            }
        }
        button.classList.toggle('d-none', !nextLayer);
        if(nextLayer){
            button.dataset.layer = String(nextLayer);
        }
    }

    function showExtraLayer(block, layerNo){
        setLayerVisibility(block, layerNo, true);
        var productSelect = block.querySelector('.layer-product-select[data-layer="' + layerNo + '"]');
        if(productSelect){
            productSelect.dispatchEvent(new Event('change', {bubbles: true}));
        }
    }

    function showNextLayer(block){
        if(!block) return;
        var button = block.querySelector('.add-layer-btn');
        var nextLayer = button ? button.dataset.layer : false;
        if(nextLayer){
            showExtraLayer(block, nextLayer);
        }
    }

    function removeExtraLayer(block, layerNo){
        if(!block || !layerNo) return;
        var startLayer = parseInt(layerNo, 10);
        if(isNaN(startLayer) || startLayer < 2) return;
        for(var currentLayer = startLayer; currentLayer <= 10; currentLayer++){
            setLayerVisibility(block, String(currentLayer), false);
        }
        refreshAddLayerButton(block);
    }

    function setupLayerToggle(block){
        for(var layerNo = 2; layerNo <= 10; layerNo++){
            setLayerVisibility(block, String(layerNo), false);
        }
        refreshAddLayerButton(block);
    }

    function setupComputedFields(block){
        block.querySelectorAll('.layer-thickness').forEach(function(input){
            input.addEventListener('input', function(){ updateTotalThickness(block); });
        });
        updateTotalThickness(block);

        var fgTypeSelect = block.querySelector('.fg-type-select');
        var bagSelect = block.querySelector('.fg-product-select');
        var productWrap = block.querySelector('.fg-product-wrap');
        var bagDimensionsWrap = block.querySelector('.bag-dimensions-wrap');
        var rollFieldsWrap = block.querySelector('.roll-fields-wrap');
        var gussetWrap = block.querySelector('.gusset-wrap');
        var gussetInput = block.querySelector('.gusset-input');

        function toggleGusset(){
            if(!bagSelect || !gussetWrap || !gussetInput) return;
            var selected = bagSelect.options[bagSelect.selectedIndex];
            var code = selected
                ? String(selected.dataset.bagCode || '').trim().toUpperCase()
                : '';
            var hide = (
                code.indexOf('SS') !== -1
                || code.startsWith('L')
                || code === 'RS'
            );
            gussetWrap.classList.toggle('d-none', hide);
            gussetInput.required = !hide && (!fgTypeSelect || fgTypeSelect.value === 'bag');
            gussetInput.disabled = hide || (fgTypeSelect && fgTypeSelect.value !== 'bag');
            if(hide){ gussetInput.value = ''; }
        }

        function toggleFgType(){
            if(!fgTypeSelect) return;
            var fgType = fgTypeSelect.value || '';
            var previousProduct = bagSelect ? bagSelect.value : '';
            var hasType = fgType === 'bag' || fgType === 'roll';
            var isBag = fgType === 'bag';
            var isRoll = fgType === 'roll';

            if(productWrap){
                productWrap.classList.toggle('d-none', !hasType);
            }
            if(bagDimensionsWrap){
                bagDimensionsWrap.classList.toggle('d-none', !isBag);
            }
            if(rollFieldsWrap){
                rollFieldsWrap.classList.toggle('d-none', !isRoll);
            }

            if(bagSelect){
                populateBagTypeOptions(bagSelect, fgType, previousProduct);
                if(
                    bagSelect.value
                    && bagSelect.options[bagSelect.selectedIndex]
                    && String(bagSelect.options[bagSelect.selectedIndex].dataset.fgType || '') !== fgType
                ){
                    bagSelect.value = '';
                }
                bagSelect.required = hasType;
                bagSelect.disabled = !hasType;
            }

            if(bagDimensionsWrap){
                bagDimensionsWrap.querySelectorAll('input, select, textarea').forEach(function(field){
                    field.disabled = !isBag;
                    if(field.classList.contains('bag-length-input')){
                        field.required = isBag;
                    }
                });
            }
            if(rollFieldsWrap){
                rollFieldsWrap.querySelectorAll('input, select, textarea').forEach(function(field){
                    field.disabled = !isRoll;
                });
            }
            toggleGusset();
        }

        if(bagSelect){
            bagSelect.addEventListener('change', toggleGusset);
        }
        if(fgTypeSelect){
            fgTypeSelect.addEventListener('change', toggleFgType);
            toggleFgType();
        } else if(bagSelect && bagTypeSource){
            populateBagTypeOptions(bagSelect, fgTypeSelect ? fgTypeSelect.value : '', bagSelect.value);
            toggleGusset();
        }

        setupPreviousRequirementLookup(block);
        setupColorReference(block);
        setupLayerToggle(block);

        var quantityUomSelect = block.querySelector('.quantity-uom-select');
        if(quantityUomSelect && quantityUomSource){
            setOptions(quantityUomSelect, quantityUomSource.innerHTML);
        }

        var printFinishSelect = block.querySelector('.print-finish-select');
        if(printFinishSelect && printFinishSource){
            setOptions(printFinishSelect, printFinishSource.innerHTML);
        }
        setupCrmMultiSelect(
            block,
            '.feature-multi',
            featureSource,
            block.dataset.featureName,
            'Select Features'
        );
        updateFeatureRules(block);
        setupLayerProductFields(block);
    }

