    function addNewDesign(){
        var idx = specIndex();
        var block = newSpecBlock(idx);
        container.appendChild(block);
        setupComputedFields(block);
        updatePreviousReqFormVisibility();
        updateLabels();
        updateAddButtons();
    }

    document.addEventListener('click', function(e){
        var addLayerButton = e.target.closest('.add-layer-btn');
        if(addLayerButton){
            showNextLayer(addLayerButton.closest('.spec-block'));
        }
        var removeLayerButton = e.target.closest('.remove-layer-btn');
        if(removeLayerButton){
            removeExtraLayer(removeLayerButton.closest('.spec-block'), removeLayerButton.dataset.layer);
        }
        if(e.target.classList.contains('add-another-btn')){
            addNewDesign();
        }
        if(e.target.classList.contains('duplicate-design-btn')){
            duplicateDesign(e.target.closest('.spec-block'));
        }
        if(e.target.classList.contains('remove-spec')){
            var blockToRemove = e.target.closest('.spec-block');
            var allBlocks = Array.prototype.slice.call(
                container.querySelectorAll('.spec-block')
            );
            if(blockToRemove && allBlocks.indexOf(blockToRemove) > 0){
                blockToRemove.remove();
                updateLabels();
                updateAddButtons();
            }
        }
    });

    if(specIndex() === 0){ addNewDesign(); }
})();
